INSERT INTO `peoples` VALUES (10304445231, 'Mark', 'mal', '1954-08-20', '', 'Southern   U.S.A.', 'fae5c9daf36ca276', 'Retail sales Manager', 'bro', 'brown', 'My profile states I am 68, but I am a very young 68.  You are only as old as you allow yourself to be.   I have been widowed for over 8 years, and since I have never had children, I\'m looking for a QUALITY young woman to start a family, or a QUALITY young woman who already has a young family established.  I\'m loyal, sincere, loving, compassionate, generous, hard working with a very good work ethic and accountability, and tend to be flexible and very humble.  I\'m also practical and conservative in my thinking.', 'sli', 'nev', 'occ', 'col', 'wid');
INSERT INTO `peoples` VALUES (10407427742, 'Rocky', 'mal', '1969-01-01', '', 'Houston, TX, USA', 'a9cdb63b06f20dfa', '', 'gre', 'fair', 'Looking for my best friend, and eternal companion. No games, no lies, all love and respect, all companionship and smiles. Please don\'t talk to me if you have had plastic surgery, I find it abhorrent and I don\'t want to be with a woman who has no confidence in herself, that she mutilates her body. I am shy, but around my loved ones I am loving and humorous, with a dry sense of humor. And if you have used filters on your pictures, DO NOT TALK TO ME!! I HATE LIARS, and you are lying about your looks. AND YES, I CAN TELL WHEN YOU USE FILTERS!! IT\"S VERY OBVIOUS!!!!', 'mus', 'nev', 'nev', 'gra', 'div');
