INSERT INTO `peoples` VALUES (68322893231, 'Renata Neves', 'fem', '1966-08-31', '', 'Rio de Janeiro, Quissamã Brazil', '1c60f14acb40c977', 'Funcionária  pública', 'haz', 'black', 'Uma mulher simples, honesta, trabalhadora que gosta de paz e harmonia, que deseja viver o melhor desta vida, com respeito, confiança com fé,  que insiste em buscar a sua felicidade, que o amor que nos impulsiona seja maior que  o medo de conhecer o desconhecido. Corajosa por está aqui, Sempre bem humorada, trata o outro bem com carinho e respeito,  sei que em algum lugar tem um amor sincero e verdadeiro que está reservado para nós dois. Um homem gentil, educado, bem humorado apaixonado que saiba tratar bem uma mulher, que tenha atitude num relacionamento sério. Nunca desista por não estar fácil. A FELICIDADE É O NOSSO ALVO. Gostaria de me comunicar ,mas o valor tá muito alto para meu recurso, estou impossibilitada no momento', 'sli', 'nev', 'nev', 'bac', 'div');
